"""Probe (v6): static counts (reference vs fast) + official verifier readings."""
import base64, json, os, pathlib, subprocess, sys

print("=== probe start ===", flush=True)
COMP = pathlib.Path("/kaggle/input/competitions/google-verifiable-quantum-circuit-compilation")
if not (COMP / "kickmix").is_dir():
    for p in pathlib.Path("/kaggle/input").rglob("verify_submission_dqi.py"):
        if (p.parents[2] / "kickmix").is_dir():
            COMP = p.parents[2]; break
print("COMP =", COMP, flush=True)
OUT = pathlib.Path("/kaggle/working")
ENV = dict(os.environ, PYTHONPATH=f"{COMP/'kickmix'}:{COMP/'verifiers'}")
VERIF = COMP / "verifiers" / "dqi" / "verify_submission_dqi.py"

GENSRC_B64 = ""
(OUT / "dqi_fast.py").write_text(base64.b64decode(GENSRC_B64).decode())

GENPROBE = """
import json
import kickmix as km
from dqi.dqi_reference_circuit import build_reference_circuit
import dqi_fast
res = {}
for (m, n, d) in [(15, 6, 4), (63, 6, 6), (255, 10, 8)]:
    k = f"{m}_{n}_{d}"
    entry = {}
    ref = build_reference_circuit(m, n, d)
    ref.to_file(f"/kaggle/working/ref_{k}.kmb", format="kmb")
    st = ref.operation_statistics()
    entry["reference"] = {"Q": ref.num_qubits, "static_T": st.num_toffoli_like, "ops": len(ref)}
    fast = dqi_fast.build_fast_circuit(m, n, d)
    fast.to_file(f"/kaggle/working/fast_{k}.kmb", format="kmb")
    st = fast.operation_statistics()
    entry["fast"] = {"Q": fast.num_qubits, "static_T": st.num_toffoli_like,
                     "ops": len(fast), "n_iter": 2 * n + 3}
    res[k] = entry
    print(json.dumps({k: entry}), flush=True)
print("JSON " + json.dumps(res), flush=True)
"""
(OUT / "gen_probe.py").write_text(GENPROBE)

RESULTS = {}
p = subprocess.run([sys.executable, str(OUT / "gen_probe.py")], capture_output=True, text=True,
                   env=ENV, cwd=str(COMP / "verifiers"), timeout=3600)
RESULTS["gen_stdout"] = p.stdout[-6000:]
RESULTS["gen_stderr"] = p.stderr[-3000:]
print("gen rc", p.returncode, flush=True)
print(p.stdout[-3000:], flush=True)
print(p.stderr[-2000:], flush=True)
for line in p.stdout.splitlines():
    if line.startswith("JSON "):
        try:
            RESULTS["static"] = json.loads(line[5:])
        except Exception:
            pass


def verify(fname, m, n, degree, shots=25600):
    path = OUT / fname
    if not path.exists():
        return {"status": "MISSING_FILE", "file": fname}
    cmd = [sys.executable, str(VERIF), str(path), "--m", str(m), "--n", str(n),
           "--degree", str(degree), "--num-shots", str(shots), "--max-workers", "2"]
    try:
        q = subprocess.run(cmd, capture_output=True, text=True, env=ENV,
                           cwd=str(COMP / "verifiers"), timeout=5400)
        try:
            return json.loads(q.stdout)
        except Exception:
            return {"status": "PARSE_FAIL", "stdout": q.stdout[-2000:], "stderr": q.stderr[-2000:]}
    except Exception as ex:
        return {"status": "RUN_FAIL", "error": repr(ex)}


RESULTS["verify_ref_15_6_4"] = verify("ref_15_6_4.kmb", 15, 6, 4)
print(json.dumps(RESULTS["verify_ref_15_6_4"], indent=1), flush=True)
RESULTS["verify_fast_15_6_4"] = verify("fast_15_6_4.kmb", 15, 6, 4)
print(json.dumps(RESULTS["verify_fast_15_6_4"], indent=1), flush=True)
RESULTS["verify_fast_63_6_6"] = verify("fast_63_6_6.kmb", 63, 6, 6)
print(json.dumps(RESULTS["verify_fast_63_6_6"], indent=1), flush=True)

(OUT / "probe_results.json").write_text(json.dumps(RESULTS, indent=1))
print("=== probe done ===", flush=True)
